void Solver::rephase() {
    // Reset the rephase counter so we start a fresh counting period
    rephases = 0;

    // Make the threshold a bit tighter (10% reduction) so that the next
    // rephase can happen earlier if the trail grows again.
    threshold = static_cast<int>(threshold * 0.90);

    // Dynamically increase the rephase limit: the more conflicts we have
    // solved, the larger the limit becomes, giving the solver more room
    // before the next forced rephase.
    // The base increment is 8192 (as in the original code) plus an
    // extra amount that grows with the number of conflicts.
    rephase_limit += 8192 + (conflicts / 1000) * 1024;

    // Update the saved phase information.
    // 70% of the time we keep the best local assignment,
    // 20% we flip it, and 10% we pick a completely random phase.
    int r = rand() % 100;
    if (r < 70) {
        // Use the best local assignment found so far
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else if (r < 90) {
        // Use the opposite of the best local assignment
        for (int i = 1; i <= vars; ++i) saved[i] = -local_best[i];
    } else {
        // Random phase assignment
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() & 1) ? 1 : -1;
    }
}
